values ($lx$david-wang-md-chandler$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$David Wang, MD (Banner Health)$lx$, null, $lx$Mandarin-speaking cardiologist at Banner Health Clinic in Chandler, accepting new patients.$lx$, $lx$錢德勒 Banner Health Clinic 會說國語的心臟內科醫師，目前接受新病患。$lx$, $lx$Dr. David Wang is a cardiologist at Banner Health Clinic, 1125 S Alma School Rd, Suite 310, in Chandler, and also sees patients at a Banner clinic on S Dobson Rd in Mesa. Dr. Wang cares for adults and is accepting new patients. Dr. Wang earned a medical degree at the University of Maryland School of Medicine, trained at the University of Maryland Medical Center, and is board certified in cardiovascular disease by the American Board of Internal Medicine. Dr. Wang speaks English and Mandarin. Languages as listed in Banner Health's Find a Doctor directory, checked November 2026.$lx$, $lx$David Wang 醫師是心臟內科醫師，在錢德勒 1125 S Alma School Rd, Suite 310 的 Banner Health Clinic 看診，也在梅薩 S Dobson Rd 的 Banner 診所看診。看診對象為成人，目前接受新病患。Wang 醫師畢業於馬里蘭大學醫學院，在 University of Maryland Medical Center 接受訓練，並持有美國內科醫學委員會（ABIM）心血管疾病專科認證。能說英語及國語。語言資訊依據 Banner Health「Find a Doctor」醫師名錄，2026 年 11 月查核。$lx$, $lx$Chandler$lx$, $lx$Greater Phoenix$lx$, $lx$1125 S Alma School Rd, Suite 310, Chandler, AZ 85286$lx$, null, $lx$(480) 733-7305$lx$, null, $lx$https://doctors.bannerhealth.com/provider/david-wang/2298021$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$David Wang, MD (Banner Health)$lx$, $lx$Chandler$lx$, $lx$medical$lx$, $lx$doctors.bannerhealth.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$doctor physician$lx$, $lx$醫師 看診$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
