values ($lx$jen-jung-pan-md-phoenix$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$Jen-Jung Pan, MD, PhD (Banner Health)$lx$, null, $lx$Mandarin-speaking gastroenterologist at the Banner - University Medicine Digestive Institute in Phoenix, accepting new patients.$lx$, $lx$鳳凰城 Banner - University Medicine 消化醫學中心會說國語的腸胃科醫師，目前接受新病患。$lx$, $lx$Dr. Jen-Jung Pan (MD, PhD) is a gastroenterologist at the Banner - University Medicine Digestive Institute, 1441 N 12th St, Floor 2, in Phoenix. Dr. Pan sees adults and seniors and is accepting new patients. Dr. Pan completed a residency at the University at Buffalo and a fellowship at the University of Florida College of Medicine, and is board certified in internal medicine by the American Board of Internal Medicine. Dr. Pan speaks Mandarin and English. Languages as listed in Banner Health's Find a Doctor directory, checked November 2026.$lx$, $lx$Jen-Jung Pan 醫師（醫學博士兼哲學博士）是腸胃科醫師，在鳳凰城 1441 N 12th St 二樓的 Banner - University Medicine Digestive Institute 看診。看診對象為成人及長者，目前接受新病患。Pan 醫師在 University at Buffalo 完成住院醫師訓練，並在佛羅里達大學醫學院完成專科研修，持有美國內科醫學委員會（ABIM）內科專科認證。能說國語及英語。語言資訊依據 Banner Health「Find a Doctor」醫師名錄，2026 年 11 月查核。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$1441 N 12th St, Floor 2, Phoenix, AZ 85006$lx$, null, $lx$(602) 521-5180$lx$, null, $lx$https://doctors.bannerhealth.com/provider/jen-jung-pan/517728$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Jen-Jung Pan, MD, PhD (Banner Health)$lx$, $lx$Phoenix$lx$, $lx$medical$lx$, $lx$doctors.bannerhealth.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$doctor physician$lx$, $lx$醫師 看診$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
